"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   portfolioItems: () => (/* binding */ portfolioItems)\n/* harmony export */ });\nconst portfolioItems = [\n    {\n        id: 1,\n        title: \"Learn Together\",\n        author: \"mahelbee\",\n        date: \"2023-10-12\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968350.png\",\n        images: [\n            \"https://images.pexels.com/photos/230544/pexels-photo-230544.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181244/pexels-photo-1181244.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181272/pexels-photo-1181272.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            `The \"Learn Together\" project was a community-based initiative aimed at fostering a love for agriculture among students. The project focused on teaching students how to grow watermelons, from seed to harvest.`,\n            `The second week of the project was dedicated to caring for the watermelon plants. We learned about the importance of watering, fertilizing, and pest control.`,\n            `In the final week of the project, we harvested the watermelons. It was a joyous occasion for everyone involved.`\n        ]\n    },\n    {\n        id: 2,\n        title: \"Learning Python Language with Students\",\n        author: \"mahelbee\",\n        date: \"2023-11-15\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968350.png\",\n        images: [\n            \"https://images.pexels.com/photos/196644/pexels-photo-196644.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/577585/pexels-photo-577585.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/2004161/pexels-photo-2004161.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            `This project was a coding workshop for students who were new to programming. I learned the basics of Python and introduced a bit to Object-Oriented Programming (OOP).`,\n            `We started with the fundamentals of Python, such as variables, data types, and control structures. The students were quick to grasp the concepts.`,\n            `The highlight of the course was when the students created their own simple games using Pygame.`\n        ]\n    },\n    {\n        id: 3,\n        title: \"Introduction to Artificial Intelligence\",\n        author: \"mahelbee\",\n        date: \"2023-12-20\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1055/1055685.png\",\n        images: [\n            \"https://images.pexels.com/photos/8386440/pexels-photo-8386440.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/8386434/pexels-photo-8386434.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/8386429/pexels-photo-8386429.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This was an introductory session on Artificial Intelligence (AI) for a group of high school students, exploring the fundamentals of machine learning and neural networks.\",\n            \"We delved into the different types of machine learning, such as supervised, unsupervised, and reinforcement learning, discussing real-world examples.\",\n            \"The session concluded with a discussion on the ethical implications of AI, a thought-provoking conversation that highlighted the importance of responsible AI development.\"\n        ]\n    },\n    {\n        id: 4,\n        title: \"Web Development Bootcamp: HTML & CSS\",\n        author: \"mahelbee\",\n        date: \"2024-01-10\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1051/1051277.png\",\n        images: [\n            \"https://images.pexels.com/photos/1779487/pexels-photo-1779487.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/160107/pexels-photo-160107.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/326503/pexels-photo-326503.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This was a hands-on workshop for beginners who wanted to learn the building blocks of the web. We created a simple, beautiful webpage from scratch using HTML and CSS.\",\n            \"The students learned how to structure a webpage using HTML and style it with CSS, covering topics such as the box model, flexbox, and responsive design.\",\n            \"The workshop culminated in a project where the students created their own personal portfolio website, a great way for them to showcase their newly acquired skills.\"\n        ]\n    },\n    {\n        id: 5,\n        title: \"Gardening 101: Preparing Your Soil\",\n        author: \"mahelbee\",\n        date: \"2024-02-18\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/2382/2382428.png\",\n        images: [\n            \"https://images.pexels.com/photos/60883/soil-dirt-agriculture-natural-60883.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/289740/pexels-photo-289740.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1400349/pexels-photo-1400349.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This workshop was all about preparing the perfect soil mix for your plants, covering topics such as composting, soil types, and the nutrients needed for a thriving garden.\",\n            \"We discussed the importance of soil health and how to create a nutrient-rich environment for plants to flourish, including making their own compost.\",\n            \"The session ended with a practical demonstration of how to test the pH of the soil, a valuable lesson for the students.\"\n        ]\n    },\n    {\n        id: 6,\n        title: \"The Magic of Photosynthesis\",\n        author: \"mahelbee\",\n        date: \"2024-03-25\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/2382/2382428.png\",\n        images: [\n            \"https://images.pexels.com/photos/220357/pexels-photo-220357.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/459301/pexels-photo-459301.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/36717/amazing-animal-beautiful-beautifull.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This was a deep dive into the magical world of photosynthesis, exploring how plants create their own food using sunlight, water, and carbon dioxide.\",\n            \"We explored the chemical reaction of photosynthesis and how it converts light energy into chemical energy.\",\n            \"The session included a fun experiment where the students observed the process of photosynthesis in action.\"\n        ]\n    },\n    {\n        id: 7,\n        title: \"Physics Fun: Understanding Kinetic Energy\",\n        author: \"mahelbee\",\n        date: \"2024-04-02\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/3304/3304400.png\",\n        images: [\n            \"https://images.pexels.com/photos/1542/pen-notes-school-stationery.jpg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/2156/sky-earth-space-working.jpg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/256517/pexels-photo-256517.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This was an interactive session on kinetic energy for a group of middle school students. We explored how motion translates to energy in everyday objects.\",\n            \"The students learned about the relationship between mass, velocity, and kinetic energy, applying concepts to real-world scenarios.\",\n            \"The session concluded with a fun competition where the students designed and built their own catapults.\"\n        ]\n    },\n    {\n        id: 8,\n        title: \"Introduction to JavaScript Algorithms\",\n        author: \"mahelbee\",\n        date: \"2024-05-11\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968292.png\",\n        images: [\n            \"https://images.pexels.com/photos/546819/pexels-photo-546819.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181263/pexels-photo-1181263.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181271/pexels-photo-1181271.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This was a session on fundamental programming algorithms and data structures using JavaScript, perfect for those looking to sharpen their problem-solving skills.\",\n            \"We covered essential algorithms such as sorting and searching, as well as data structures like arrays and linked lists.\",\n            \"The session ended with a coding challenge where the students competed to solve algorithmic problems.\"\n        ]\n    },\n    {\n        id: 9,\n        title: \"Urban Farming: Growing in Small Spaces\",\n        author: \"mahelbee\",\n        date: \"2024-06-22\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/2382/2382428.png\",\n        images: [\n            \"https://images.pexels.com/photos/2519374/pexels-photo-2519374.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/2519375/pexels-photo-2519375.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/2519376/pexels-photo-2519376.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This workshop was all about growing your own food in an urban environment, covering techniques for vertical gardening, container gardening, and hydroponics basics.\",\n            \"The students learned how to create their own vertical gardens using recycled materials and discussed water conservation.\",\n            \"The session concluded with a visit to a local urban farm, an inspiring experience for the students.\"\n        ]\n    },\n    {\n        id: 10,\n        title: \"Exploring Neural Networks\",\n        author: \"mahelbee\",\n        date: \"2024-07-30\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1055/1055685.png\",\n        images: [\n            \"https://images.pexels.com/photos/373543/pexels-photo-373543.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/574071/pexels-photo-574071.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/574073/pexels-photo-574073.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This was a follow-up to our AI intro session, focusing specifically on the architecture and function of neural networks.\",\n            \"We explored the different types of neural networks, such as CNNs and RNNs, using real-world examples.\",\n            \"The session concluded with a hands-on exercise where the students built their own neural network using TensorFlow.\"\n        ]\n    },\n    {\n        id: 11,\n        title: \"The Science of Composting\",\n        author: \"mahelbee\",\n        date: \"2024-08-05\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/2382/2382428.png\",\n        images: [\n            \"https://images.pexels.com/photos/3952048/pexels-photo-3952048.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/4481326/pexels-photo-4481326.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/691668/pexels-photo-691668.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This workshop was all about turning your kitchen scraps into nutrient-rich soil, covering the do's and don'ts of composting.\",\n            \"The students learned about the science behind composting and how to create the perfect compost pile.\",\n            \"The session concluded with a visit to a community garden to see composting in action.\"\n        ]\n    },\n    {\n        id: 12,\n        title: \"Advanced CSS: Animations and Transitions\",\n        author: \"mahelbee\",\n        date: \"2024-09-19\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1051/1051277.png\",\n        images: [\n            \"https://images.pexels.com/photos/574071/pexels-photo-574071.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181298/pexels-photo-1181298.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181316/pexels-photo-1181316.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"This workshop was all about taking your web design skills to the next level with fluid animations and transitions with pure CSS.\",\n            \"We explored advanced CSS properties such as transforms, transitions, and keyframes.\",\n            \"The workshop culminated in a project where the students created their own animated webpage.\"\n        ]\n    },\n    {\n        id: 13,\n        title: \"Building a REST API with Node.js & Express\",\n        author: \"mahelbee\",\n        date: \"2024-10-05\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968322.png\",\n        images: [\n            \"https://images.pexels.com/photos/11035471/pexels-photo-11035471.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/11035380/pexels-photo-11035380.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/577585/pexels-photo-577585.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A comprehensive workshop on backend development, focusing on creating robust REST APIs using Node.js and the Express framework.\",\n            \"Participants learned about routing, middleware, request handling, and connecting to a MongoDB database.\",\n            \"The final project involved building a complete API for a simple blogging platform.\"\n        ]\n    },\n    {\n        id: 14,\n        title: \"Data Visualization with D3.js\",\n        author: \"mahelbee\",\n        date: \"2024-11-12\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968292.png\",\n        images: [\n            \"https://images.pexels.com/photos/3861958/pexels-photo-3861958.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/3861964/pexels-photo-3861964.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/3862632/pexels-photo-3862632.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"An advanced session for frontend developers on creating interactive and dynamic data visualizations for the web using D3.js.\",\n            \"We covered D3's core concepts, data binding, and creating bar charts, line graphs, and scatter plots.\",\n            \"Students were challenged to visualize a dataset of their choice, resulting in a gallery of impressive projects.\"\n        ]\n    },\n    {\n        id: 15,\n        title: \"Introduction to Docker for Developers\",\n        author: \"mahelbee\",\n        date: \"2024-12-01\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/919/919853.png\",\n        images: [\n            \"https://images.pexels.com/photos/1779487/pexels-photo-1779487.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/546819/pexels-photo-546819.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/326503/pexels-photo-326503.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A practical workshop aimed at simplifying development workflows and deployment using Docker containerization.\",\n            \"We covered writing Dockerfiles, managing containers with Docker Compose, and setting up isolated development environments.\",\n            \"The session helped developers understand how to ship applications that run consistently across any infrastructure.\"\n        ]\n    },\n    {\n        id: 16,\n        title: \"Creative Coding with p5.js\",\n        author: \"mahelbee\",\n        date: \"2025-01-15\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968292.png\",\n        images: [\n            \"https://images.pexels.com/photos/2007401/pexels-photo-2007401.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1638324/pexels-photo-1638324.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/346529/pexels-photo-346529.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A fun, artistic workshop exploring the basics of creative coding and generative art using the p5.js library.\",\n            \"Students learned how to draw with code, create animations, and respond to user input to make interactive art pieces.\",\n            \"The final showcase was a vibrant collection of digital sketches and animations.\"\n        ]\n    },\n    {\n        id: 17,\n        title: \"State Management in React with Zustand\",\n        author: \"mahelbee\",\n        date: \"2025-02-20\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1126/1126012.png\",\n        images: [\n            \"https://images.pexels.com/photos/11035474/pexels-photo-11035474.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/160107/pexels-photo-160107.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/1181298/pexels-photo-1181298.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A focused session on modern, simplified state management in React applications using the Zustand library.\",\n            \"We compared Zustand to other solutions like Redux and Context API, highlighting its simplicity and performance.\",\n            \"Participants refactored a small application to use Zustand for managing global state.\"\n        ]\n    },\n    {\n        id: 18,\n        title: \"Building a Serverless Function with Netlify\",\n        author: \"mahelbee\",\n        date: \"2025-03-10\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1051/1051277.png\",\n        images: [\n            \"https://images.pexels.com/photos/5926382/pexels-photo-5926382.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/5926389/pexels-photo-5926389.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/607812/pexels-photo-607812.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"An introduction to the world of serverless architecture by building a real-world function hosted on Netlify.\",\n            \"We wrote a serverless function in JavaScript to handle a form submission and integrate with a third-party API.\",\n            \"This workshop demonstrated how to add powerful backend functionality to static sites without managing a server.\"\n        ]\n    },\n    {\n        id: 19,\n        title: \"TypeScript for Beginners\",\n        author: \"mahelbee\",\n        date: \"2025-04-02\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968386.png\",\n        images: [\n            \"https://images.pexels.com/photos/1181271/pexels-photo-1181271.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/574071/pexels-photo-574071.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/574073/pexels-photo-574073.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A beginner-friendly introduction to TypeScript, showing how adding types to JavaScript can prevent bugs and improve code quality.\",\n            \"We covered basic types, interfaces, and how to configure a project to use TypeScript.\",\n            \"Students converted a small JavaScript project to TypeScript, experiencing the benefits firsthand.\"\n        ]\n    },\n    {\n        id: 20,\n        title: \"GraphQL API with Apollo Server\",\n        author: \"mahelbee\",\n        date: \"2025-05-21\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968322.png\",\n        images: [\n            \"https://images.pexels.com/photos/4397839/pexels-photo-4397839.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/4397840/pexels-photo-4397840.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/4397841/pexels-photo-4397841.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A workshop on building flexible and efficient APIs using GraphQL with Apollo Server.\",\n            \"We designed a GraphQL schema, wrote resolvers, and connected it to a PostgreSQL database.\",\n            \"Participants learned how GraphQL allows clients to request exactly the data they need and nothing more.\"\n        ]\n    },\n    {\n        id: 21,\n        title: \"Web Accessibility (a11y) Fundamentals\",\n        author: \"mahelbee\",\n        date: \"2025-06-18\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1051/1051277.png\",\n        images: [\n            \"https://images.pexels.com/photos/3184423/pexels-photo-3184423.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/3184431/pexels-photo-3184431.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/3184465/pexels-photo-3184465.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"An essential workshop for all web developers on the principles of web accessibility (a11y).\",\n            \"We covered semantic HTML, ARIA attributes, keyboard navigation, and screen reader testing.\",\n            \"The goal was to equip developers with the knowledge to build websites that are usable by everyone.\"\n        ]\n    },\n    {\n        id: 22,\n        title: \"Automated Testing with Jest and React Testing Library\",\n        author: \"mahelbee\",\n        date: \"2025-07-09\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1126/1126012.png\",\n        images: [\n            \"https://images.pexels.com/photos/4065624/pexels-photo-4065624.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/4065625/pexels-photo-4065625.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/4065626/pexels-photo-4065626.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A hands-on session on writing unit and integration tests for React components.\",\n            \"We used Jest as a test runner and React Testing Library to write user-centric tests that improve confidence in our code.\",\n            \"Participants wrote tests for an existing application, learning how to mock functions and test component interactions.\"\n        ]\n    },\n    {\n        id: 23,\n        title: \"Introduction to 3D Graphics with Three.js\",\n        author: \"mahelbee\",\n        date: \"2025-08-14\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/5968/5968292.png\",\n        images: [\n            \"https://images.pexels.com/photos/1036808/pexels-photo-1036808.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/158771/new-zealand-lake-wakatipu-queenstown-158771.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/2356045/pexels-photo-2356045.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"An exciting introduction to creating 3D graphics on the web using Three.js.\",\n            \"We learned about scenes, cameras, renderers, geometry, and materials to build and animate a simple 3D object.\",\n            \"The workshop opened up a new dimension of web development possibilities for the participants.\"\n        ]\n    },\n    {\n        id: 24,\n        title: \"Cybersecurity Basics for Web Developers\",\n        author: \"mahelbee\",\n        date: \"2025-09-05\",\n        icon: \"https://cdn-icons-png.flaticon.com/512/1055/1055685.png\",\n        images: [\n            \"https://images.pexels.com/photos/60504/security-protection-anti-virus-software-60504.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/247968/pexels-photo-247968.jpeg?auto=compress&cs=tinysrgb&w=600\",\n            \"https://images.pexels.com/photos/5380664/pexels-photo-5380664.jpeg?auto=compress&cs=tinysrgb&w=600\"\n        ],\n        desc: [\n            \"A crucial session covering common web security vulnerabilities and how to prevent them.\",\n            \"We covered topics like Cross-Site Scripting (XSS), Cross-Site Request Forgery (CSRF), and SQL injection.\",\n            \"Developers learned practical techniques to write more secure code and protect their applications and users.\"\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/portfolioData.ts\n");

